import json,sys
d=json.load(open('mat.json'))
def walk(n,out):
    if isinstance(n,dict):
        if n.get('type')=='text': out.append(n.get('text',''))
        elif n.get('type')=='heading': out.append('\n\n## '+n.get('text','')+'\n')
        elif n.get('type')=='paragraph': out.append('\n')
        elif n.get('type')=='listItem': out.append('\n- ')
        for k,v in n.items(): walk(v,out)
    elif isinstance(n,list):
        for i in n: walk(i,out)
